// IEC Information
what_is_iec: "IEC என்றால் என்ன?",
iec_description_1: "IEC (இறக்குமதி ஏற்றுமதி குறியீடு) என்பது DGFT ஆல் வழங்கப்படும் 10 இலக்க எண்ணெழுத்து குறியீடு.",
iec_description_2: "இந்தியாவில் இறக்குமதி அல்லது ஏற்றுமதி வணிகத்தில் ஈடுபடும் தனிநபர்கள்/நிறுவனங்களுக்கு இது கட்டாயமாகும்.",
iec_description_3: "சுங்க அனுமதி, அந்நிய செலாவணி பரிவர்த்தனைகள் மற்றும் சர்வதேச வணிகத்திற்கு தேவை.",
iec_description_4: "வாழ்நாள் முழுவதும் செல்லுபடியாகும், புதுப்பித்தல் தேவையில்லை.",

benefits_of_iec_registration: "IEC பதிவின் நன்மைகள்:",
iec_benefit_1: "சர்வதேச வணிக செயல்பாடுகளை (இறக்குமதி மற்றும் ஏற்றுமதி) இயக்குகிறது.",
iec_benefit_2: "DGFT இலிருந்து ஏற்றுமதி ஊக்குவிப்பு மற்றும் திட்டங்களுக்கான அணுகல்.",
iec_benefit_3: "சுங்க நடைமுறைகள் மற்றும் ஆவணப்படுத்தலை எளிமைப்படுத்துகிறது.",
iec_benefit_4: "உலக சந்தைகளில் வணிக நம்பகத்தன்மையை மேம்படுத்துகிறது.",
iec_benefit_5: "ஆண்டு இணக்கம் அல்லது தாக்கல் தேவைகள் இல்லை.",
dsc_definition_1: "டிஜிட்டல் கையொப்ப சான்றிதழ் ஒரு பாதுகாப்பான டிஜிட்டல் விசை",
dsc_definition_2: "டிஜிட்டல் பரிவர்த்தனைகளில் உங்கள் அடையாளத்தை அங்கீகரிக்கப் பயன்படுத்தப்படுகிறது",
dsc_definition_3: "பல்வேறு அரசு படிவங்கள் மற்றும் ஆவணங்களை தாக்கல் செய்ய தேவை",
dsc_definition_4: "மின்னணு ஆவணங்களுக்கு சட்டப்பூர்வ செல்லுபடியாக்கத்தை வழங்குகிறது",
dsc_definition_5: "GST திருப்பங்கள், வருமான வரி தாக்கல்கள் மற்றும் பலவற்றிற்கு அவசியம்",
uses_of_dsc: "DSC இன் பயன்கள்:",
dsc_use_1: "GST திருப்பங்கள் மற்றும் பிற வரி ஆவணங்களை தாக்கல் செய்தல்",
dsc_use_2: "இ-டெண்டரிங் மற்றும் அரசு கொள்முதல்",
dsc_use_3: "நிறுவன பதிவு மற்றும் இணக்க தாக்கல்கள்",
dsc_use_4: "வங்கி மற்றும் நிதி பரிவர்த்தனைகள்",
dsc_use_5: "சட்ட ஆவண அங்கீகாரம்",
important_notes: "முக்கிய குறிப்புகள்:",
dsc_note_1: "DSC பொதுவாக வழங்கப்பட்ட தேதியிலிருந்து 1-3 ஆண்டுகளுக்கு செல்லுபடியாகும்",
dsc_note_2: "நீங்கள் DSC ஐ USB டோக்கனில் அல்லது மென்பொருள் சான்றிதழாக பெறுவீர்கள்",
dsc_note_3: "உங்கள் DSC கடவுச்சொல்லை பாதுகாப்பாகவும் ரகசியமாகவும் வைத்திருக்கவும்",
dsc_note_4: "தொடர்ந்து பயன்படுத்துவதற்கு காலாவதியாகும் முன் புதுப்பித்தல் தேவை",
dsc_application_submitted_processing: "உங்கள் DSC பதிவு விண்ணப்பம் சமர்ப்பிக்கப்பட்டு, தற்போது செயலாக்கப்படுகிறது. முன்னேற்றப் பிரிவில் முன்னேற்றத்தைக் கண்காணிக்கலாம்.",
submit_dsc_application: "DSC விண்ணப்பத்தை சமர்ப்பிக்கவும் ({{progress}}% முடிந்தது)",
file_size_is: "கோப்பு அளவு",
iec_certificate: "IEC சான்றிதழ்",
from_iec_registration: "IEC பதிவிலிருந்து",
what_is_icegate: "🌐 ICEGATE என்றால் என்ன?",
icegate_definition_1: "• இந்திய சுங்க மின்னணு நுழைவாயில் வணிகம் மற்றும் சுங்க அனுமதிக்கான ஒரு இணையதளம்",
icegate_definition_2: "• பல்வேறு சுங்க ஆவணங்களுக்கு (எ.கா., பில் ஆஃப் என்ட்ரி, ஷிப்பிங் பில்) இ-தாக்கல் சேவைகளை வழங்குகிறது",
icegate_definition_3: "• சுங்க கட்டணங்கள் மற்றும் பிற கட்டணங்களை ஆன்லைனில் செலுத்துவதற்கு உதவுகிறது",
icegate_definition_4: "• இந்திய சுங்கத்துடன் தொடர்பு கொள்ள இறக்குமதியாளர்கள் மற்றும் ஏற்றுமதியாளர்களுக்கு அவசியம்",
benefits_of_icegate: "📋 ICEGATE பதிவின் நன்மைகள்:",
icegate_benefit_1: "• ஒழுங்குபடுத்தப்பட்ட சுங்க அனுமதி செயல்முறை",
icegate_benefit_2: "• இறக்குமதி மற்றும் ஏற்றுமதி சரக்குகளை வேகமாக செயலாக்குதல்",
icegate_benefit_3: "• சுங்க தரவு மற்றும் நிலை புதுப்பிப்புகளுக்கு ஆன்லைன் அணுகல்",
icegate_benefit_4: "• குறைந்த ஆவண வேலைகள் மற்றும் கையேடு தலையீடு",
icegate_benefit_5: "• வணிக செயல்பாடுகளில் மேம்பட்ட வெளிப்படைத்தன்மை மற்றும் செயல்திறன்",
icegate_application_submitted_processing: "உங்கள் ICEGATE பதிவு விண்ணப்பம் சமர்ப்பிக்கப்பட்டு, தற்போது செயலாக்கப்படுகிறது. முன்னேற்றப் பிரிவில் முன்னேற்றத்தைக் கண்காணிக்கலாம்.",
