adcode_benefit_2: "• சுங்க அனுமதி செயல்முறைகளை எளிதாக்குகிறது",
adcode_benefit_3: "• கடன் கடிதத்தை (LC) திறக்க தேவை",
adcode_benefit_4: "• வங்கி உத்தரவாதம் மற்றும் பிற வணிக நிதி வசதிகளை இயக்குகிறது",
