    // FAQ Questions and Answers
    faq_q1: "గోఫార్మ్లీకనెక్ట్‌లో నా వ్యవసాయాన్ని ఎలా రిజిస్టర్ చేయాలి?",
    faq_a1:
      "రిజిస్ట్రేషన్ సరళమైనది మరియు ఉచితం. 'ప్రారంభించండి'పై క్లిక్ చేయండి, మీ ప్రాథమిక వ్యవసాయ వివరాలను నింపండి, అవసరమైన డాక్యుమెంట్లను అప్‌లోడ్ చేయండి, మరియు మీ మొబైల్ నంబర్‌ను ధృవీకరించండి. మా బృందం 24 గంటలలో మీ ఖాతాను సమీక్షించి, యాక్టివేట్ చేస్తుంది.",
    faq_q2: "ప్లాట్‌ఫారమ్ ద్వారా నేను ఏ డాక్యుమెంట్లను ఫైల్ చేయవచ్చు?",
    faq_a2:
      "మీరు పంట బీమా దరఖాస్తులు, సబ్సిడీ ఫారమ్‌లు, రుణ దరఖాస్తులు, భూమి రికార్డులు, సాయిల్ హెల్త్ కార్డులు మరియు నియమ నిబంధనల సర్టిఫికెట్లతో సహా అన్ని ప్రధాన వ్యవసాయ డాక్యుమెంట్లను ఫైల్ చేయవచ్చు. మా సిస్టమ్ 50+ డాక్యుమెంట్ రకాలకు మద్దతు ఇస్తుంది.",
    faq_q3: "గోఫార్మ్లీకనెక్ట్‌లో నా డేటా సురక్షితంగా ఉందా?",
    faq_a3:
      "ఖచ్చితంగా. మేము బ్యాంక్-గ్రేడ్ ఎన్‌క్రిప్షన్‌ను ఉపయోగిస్తాము మరియు కఠినమైన డేటా రక్షణ ప్రోటోకాల్‌లను అనుసరిస్తాము. మీ సమాచారం సురక్షితంగా నిల్వ చేయబడుతుంది మరియు మీ సమ్మతి లేకుండా మూడవ పక్షాలతో ఎప్పుడూ షేర్ చేయబడదు. మేము అన్ని ప్రభుత్వ డేటా రక్షణ నియమాలకు కూడా అనుగుణంగా ఉన్నాము.",
    faq_q4: "పంట దిగుబడి అంచనాలు ఎంత ఖచ్చితమైనవి?",
    faq_a4:
      "మా AI-ఆధారిత అంచనాలు 85-90% ఖచ్చితత్వ రేటును కలిగి ఉన్నాయి. మేము శాటిలైట్ చిత్రాలు, వాతావరణ డేటా, మట్టి పరిస్థితులు మరియు చారిత్రక నమూనాలను ఉపయోగించి నమ్మదగిన అంచనాలను అందిస్తాము. అయితే, మీ వ్యవసాయ నైపుణ్యంతో పాటు అంచనాలను మార్గదర్శకంగా ఉపయోగించాలి.",
    faq_q5: "గోఫార్మ్లీకనెక్ట్‌ను ఆఫ్‌లైన్‌లో యాక్సెస్ చేయవచ్చా?",
    faq_a5:
      "అవును, మా మొబైల్ యాప్ ఆఫ్‌లైన్ సామర్థ్యాలను కలిగి ఉంది. మీరు ఇంటర్నెట్ లేకుండా మీ డేటాను చూడవచ్చు, ఫారమ్‌లను నింపవచ్చు మరియు ట్యుటోరియల్స్‌ను యాక్సెస్ చేయవచ్చు. మీరు మళ్లీ ఆన్‌లైన్‌లోకి వచ్చిన తర్వాత, అన్ని మార్పులు ఆటోమేటిక్‌గా క్లౌడ్‌కు సమకాలీకరించబడతాయి.",
    faq_q6: "ఖర్చులు ఏమిటి?",
    faq_a6:
      "అన్ని రైతులకు ప్రాథమిక ఫీచర్లు పూర్తిగా ఉచితం. అధునాతన విశ్లేషణలు, ప్రాధాన్య మద్దతు, మరియు అదనపు నిల్వ వంటి ప్రీమియం ఫీచర్లు ₹99/నెల నుండి ప్రారంభమయ్యే సరసమైన సబ్‌స్క్రిప్షన్ ప్లాన్‌ల ద్వారా అందుబాటులో ఉన్నాయి.",
    faq_q7: "సాంకేతిక మద్దతును నేను ఎలా పొందగలను?",
    faq_a7:
      "మేము ఫోన్ (1800-3010-1000), ఇమెయిల్, లైవ్ చాట్, మరియు వాట్సాప్ ద్వారా 24/7 మద్దతును అందిస్తాము. మా వ్యవసాయ నిపుణులు ఏదైనా సాంకేతిక లేదా వ్యవసాయ సంబంధిత ప్రశ్నలతో మీకు సహాయం చేయడానికి ఎల్లప్పుడూ సిద్ధంగా ఉన్నారు.",
    faq_q8: "గోఫార్మ్లీకనెక్ట్‌ను ఇతర వ్యవసాయ సాధనాలతో ఇంటిగ్రేట్ చేయవచ్చా?",
    faq_a8:
      "అవును, గోఫార్మ్లీకనెక్ట్ ప్రముఖ వ్యవసాయ సామగ్రి, వాతావరణ స్టేషన్లు మరియు ఆర్థిక సేవలతో ఇంటిగ్రేట్ అవుతుంది. మేము కస్టమ్ ఇంటిగ్రేషన్‌ల కోసం APIలను అందుబాటులో ఉంచాము మరియు ప్రధాన వ్యవసాయ సాంకేతిక సరఫరాదారులతో భాగస్వామ్యాలను కలిగి ఉన్నాము.",

