interface LanguageProviderProps {
  children: ReactNode
}

// Merge additional translations into the main translations object
Object.keys(additionalTranslations).forEach(lang => {
  if (translations[lang]) {
    translations[lang] = { ...translations[lang], ...additionalTranslations[lang] };
  } else {
    translations[lang] = additionalTranslations[lang];
  }
});

export function LanguageProvider({ children }: LanguageProviderProps) {
  const [language, setLanguage] = useState<string>("en")

  useEffect(() => {
    // Load saved language preference - only on client side
    if (typeof window !== 'undefined') {
      const savedLanguage = localStorage.getItem("preferredLanguage") || "en"
      setLanguage(savedLanguage)
    }
  }, [])

  const changeLanguage = (lang: string) => {
    setLanguage(lang)
    if (typeof window !== 'undefined') {
      localStorage.setItem("preferredLanguage", lang)
    }
  }

  const t = (key: string, replacements?: Record<string, string>): string => {
    let translated = translations[language]?.[key] || translations["en"]?.[key] || key
    if (replacements) {
      for (const placeholder in replacements) {
        translated = translated.replace(`{{${placeholder}}}`, replacements[placeholder])
      }
    }
    return translated
  }

  return (
    <LanguageContext.Provider value={{ language, setLanguage: changeLanguage, t }}>{children}</LanguageContext.Provider>
  )
}

export function useLanguage() {
  const context = useContext(LanguageContext)
  if (context === undefined) {
    throw new Error("useLanguage must be used within a LanguageProvider")
  }
  return context
}
